//! End-to-end tests for the telemetry pipeline: a real UDP socket, the real
//! parser, and the real shared snapshot.
//!
//! Unit tests cover each stage in isolation. These exist to catch the failures
//! that only appear once the stages are wired together — a datagram that parses
//! but never reaches the snapshot, a packet counter that does not advance, a
//! malformed datagram that takes the receive thread down with it.
//!
//! Every datagram is generated by `telemetry::synthetic`. Nothing here replays
//! captured driving data.

use std::net::UdpSocket;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

use veloryft_hud::telemetry::snapshot::Shared;
use veloryft_hud::telemetry::synthetic::{self, Frame};
use veloryft_hud::telemetry::{receiver, visibility};

/// How long a test waits for the receive thread to publish a snapshot before
/// giving up. Generous: this is a liveness bound, not a performance assertion.
const SETTLE_TIMEOUT: Duration = Duration::from_secs(5);

/// Starts the receiver on a free port and returns the snapshot, a socket
/// already pointed at it, and a counter of callback invocations.
fn start_receiver() -> (Arc<Shared>, UdpSocket, Arc<AtomicUsize>) {
    let shared = Arc::new(Shared::new());
    let callbacks = Arc::new(AtomicUsize::new(0));

    // Ask the OS for a free port, then hand that number to the receiver. There
    // is a race between closing this probe and the receiver binding, so retry.
    for _ in 0..32 {
        let port = {
            let probe = UdpSocket::bind(("127.0.0.1", 0)).expect("the OS can hand out a port");
            probe
                .local_addr()
                .expect("a bound socket has an address")
                .port()
        };

        let counter = callbacks.clone();
        if receiver::spawn(shared.clone(), port, move |_frame| {
            counter.fetch_add(1, Ordering::Relaxed);
        })
        .is_ok()
        {
            let sender = UdpSocket::bind(("127.0.0.1", 0)).expect("a sending socket");
            sender
                .connect(("127.0.0.1", port))
                .expect("connecting a UDP socket to loopback");
            return (shared, sender, callbacks);
        }
    }
    panic!("could not bind a free UDP port after 32 attempts");
}

/// Blocks until `condition` holds or [`SETTLE_TIMEOUT`] elapses.
fn wait_until(condition: impl Fn() -> bool) -> bool {
    let deadline = Instant::now() + SETTLE_TIMEOUT;
    while Instant::now() < deadline {
        if condition() {
            return true;
        }
        std::thread::sleep(Duration::from_millis(5));
    }
    false
}

#[test]
fn an_fh6_datagram_reaches_the_snapshot_with_its_values_intact() {
    let (shared, sender, _) = start_receiver();
    let frame = Frame::driving();

    sender
        .send(&synthetic::encode_fh6(&frame))
        .expect("sending one datagram");

    assert!(
        wait_until(|| shared.latest()._pkt > 0),
        "the receiver never published a snapshot"
    );

    let snapshot = shared.latest();
    assert_eq!(snapshot.fmt, "FH6");
    assert_eq!(snapshot.rpm, frame.engine_rpm);
    assert_eq!(snapshot.max_rpm, frame.engine_max_rpm);
    assert_eq!(snapshot.car_ordinal, frame.car_ordinal);
    assert_eq!(snapshot.gear, Some(frame.gear));
    // Speed arrives in m/s and is displayed in km/h.
    let expected_kmh = frame.speed_ms * 3.6;
    assert!((snapshot.speed.expect("speed is present") - expected_kmh).abs() < 0.01);
}

#[test]
fn the_packet_counter_advances_once_per_datagram() {
    let (shared, sender, callbacks) = start_receiver();
    let frame = Frame::driving();
    let datagram = synthetic::encode_fh6(&frame);

    for _ in 0..5 {
        sender.send(&datagram).expect("sending a datagram");
    }

    // UDP may drop on loopback under load, so assert monotonic progress rather
    // than an exact count.
    assert!(
        wait_until(|| shared.latest()._pkt >= 3),
        "expected several packets to be counted, saw {}",
        shared.latest()._pkt
    );
    // The receive thread stores the snapshot (making `_pkt` visible above)
    // before invoking the callback, so the callback count can briefly lag
    // behind `_pkt` even once every datagram has been accepted. Poll instead
    // of sampling once, or this flakes whenever the two steps get scheduled
    // apart under load.
    assert!(
        wait_until(|| callbacks.load(Ordering::Relaxed) >= 3),
        "the per-packet callback should fire for every accepted datagram, saw {}",
        callbacks.load(Ordering::Relaxed)
    );
}

#[test]
fn a_truncated_datagram_is_dropped_without_killing_the_receiver() {
    let (shared, sender, _) = start_receiver();

    // Shorter than the smallest known format: nothing can be read from it.
    sender.send(&[0_u8; 64]).expect("sending a runt datagram");
    sender.send(&[0_u8; 231]).expect("one byte short of Sled");

    // A valid datagram afterwards must still be processed, which proves the
    // receive loop survived the malformed ones.
    sender
        .send(&synthetic::encode_fh6(&Frame::driving()))
        .expect("sending a valid datagram");

    assert!(
        wait_until(|| shared.latest()._pkt > 0),
        "the receiver stopped after a malformed datagram"
    );
    assert_eq!(shared.latest().fmt, "FH6");
}

#[test]
fn an_oversized_datagram_does_not_confuse_the_parser() {
    let (shared, sender, _) = start_receiver();

    // Longer than FH6. The parser reads by offset and must ignore the tail.
    let mut oversized = synthetic::encode_fh6(&Frame::driving());
    oversized.extend_from_slice(&[0xFF_u8; 200]);
    sender
        .send(&oversized)
        .expect("sending an oversized datagram");

    assert!(
        wait_until(|| shared.latest()._pkt > 0),
        "an oversized datagram was not accepted"
    );
    assert_eq!(shared.latest().rpm, Frame::driving().engine_rpm);
}

#[test]
fn each_wire_format_is_recognized_end_to_end() {
    for (label, datagram) in [
        ("Sled", synthetic::encode_sled(&Frame::driving())),
        ("Dash", synthetic::encode_dash(&Frame::driving())),
        ("FH6", synthetic::encode_fh6(&Frame::driving())),
    ] {
        let (shared, sender, _) = start_receiver();
        sender.send(&datagram).expect("sending a datagram");

        assert!(
            wait_until(|| shared.latest()._pkt > 0),
            "no snapshot for the {label} format"
        );
        assert_eq!(shared.latest().fmt, label);
    }
}

#[test]
fn the_hud_hides_in_menus_and_appears_while_driving() {
    let (shared, sender, _) = start_receiver();

    // A car parked in a menu: is_race_on cleared, engine at idle, no input.
    // In free roam the game also sends is_race_on = 0 while driving, so the
    // engine and speed are what actually distinguish the two.
    let menu = Frame {
        race_on: 0,
        engine_rpm: 820.0,
        speed_ms: 0.0,
        accel_input: 0,
        brake_input: 0,
        clutch_input: 0,
        steer: 0,
        ..Frame::driving()
    };
    sender.send(&synthetic::encode_fh6(&menu)).expect("sending");

    assert!(
        wait_until(|| shared.latest()._pkt > 0),
        "no snapshot arrived"
    );
    assert!(
        !visibility::is_hud_visible(&shared.latest(), 0.0),
        "the HUD must stay hidden in menus"
    );

    sender
        .send(&synthetic::encode_fh6(&Frame::driving()))
        .expect("sending");
    assert!(
        wait_until(|| visibility::is_hud_visible(&shared.latest(), 0.0)),
        "the HUD must appear once the player is driving"
    );
}

#[test]
fn a_scripted_cutscene_does_not_bring_the_hud_back() {
    let (shared, sender, _) = start_receiver();

    // The car moves quickly but the engine is at idle and the player is not
    // touching anything: that is a camera flythrough, not driving.
    let cutscene = Frame {
        race_on: 0,
        engine_rpm: 900.0,
        speed_ms: 30.0,
        accel_input: 0,
        brake_input: 0,
        clutch_input: 0,
        steer: 0,
        ..Frame::driving()
    };
    sender
        .send(&synthetic::encode_fh6(&cutscene))
        .expect("sending");

    assert!(
        wait_until(|| shared.latest()._pkt > 0),
        "no snapshot arrived"
    );
    assert!(
        !visibility::is_hud_visible(&shared.latest(), 0.0),
        "movement without driver input must not show the HUD"
    );
}

#[test]
fn a_sled_packet_never_shows_the_hud() {
    // Sled carries no pedal, speed or gear data, so there is nothing to draw.
    let (shared, sender, _) = start_receiver();
    sender
        .send(&synthetic::encode_sled(&Frame::driving()))
        .expect("sending");

    assert!(
        wait_until(|| shared.latest()._pkt > 0),
        "no snapshot arrived"
    );
    assert_eq!(shared.latest().fmt, "Sled");
    assert!(!visibility::is_hud_visible(&shared.latest(), 0.0));
}

#[test]
fn the_hud_hides_again_once_telemetry_goes_stale() {
    let (shared, sender, _) = start_receiver();
    sender
        .send(&synthetic::encode_fh6(&Frame::driving()))
        .expect("sending");

    assert!(
        wait_until(|| visibility::is_hud_visible(&shared.latest(), 0.0)),
        "the HUD never became visible"
    );

    // The game closing looks exactly like packets stopping.
    let stale_age = visibility::STALE_S + 0.5;
    assert!(
        !visibility::is_hud_visible(&shared.latest(), stale_age),
        "the HUD must disappear when telemetry stops arriving"
    );
}
